<template>
    <div class="chat-dialog-container" v-loading="showMessageAreaLoading">
        <!-- 对话消息列表区域 -->
        <div ref="msgListRef" class="chat-messages-area" @scroll="handleScroll">
            <!-- 加载更多提示（顶部） -->
            <div v-if="loadingType === 'more'" class="loading-more">
                <div class="loading-spinner"></div>
                <span>{{ t("loading") }}</span>
            </div>

            <!-- 消息列表 -->
            <div
                v-for="item in messageList"
                :key="item.id"
                class="message-item"
                :class="{ 'message-user': item.role === MSG_ROLE_USER }"
            >
                <!-- 用户消息 -->
                <div v-if="item.role === MSG_ROLE_USER" class="user-message">
                    <div class="message-content">
                        <msg-item-text
                            :content="item.content"
                            :role="item.role"
                            :isMarkdown="item.isMarkdown"
                            :typing="false"
                            :showLoading="item.showLoading"
                            theme="text-tool"
                            @onFinish="onFinish(item.id)"
                        >
                            <template #footer>
                                <div class="message-time user-time">
                                    {{ convertUtcToLocal(item.createTime) }}
                                </div>
                            </template>
                        </msg-item-text>
                    </div>
                    <div class="user-avatar">
                        <l-img
                            :src="'/static/images/default_avatar.png'"
                            w="32px"
                            h="32px"
                            radius="16px"
                            fit="cover"
                        />
                    </div>
                </div>

                <!-- AI消息 -->
                <div v-else class="assistant-message">
                    <div class="assistant-avatar">
                        <l-img
                            :src="'/static/logo3.png'"
                            w="32px"
                            h="32px"
                            radius="16px"
                            fit="cover"
                        />
                    </div>
                    <div class="message-content">
                        <!-- 失败状态显示重试组件 -->
                        <template v-if="item.messageStatus === MESSAGE_STATUS.FAILED">
                            <message-retry 
                                :is-retrying="item.messageStatus === MESSAGE_STATUS.SENDING"
                                @onRetry="handleRetryMessage(item.id)"
                            />
                            <!-- 失败状态的时间显示 -->
                            <div class="message-time assistant-time">
                                {{ formatTime(item, item.role) }}
                            </div>
                        </template>
                        
                        <!-- 正常状态显示消息组件 -->
                        <msg-item-text
                            v-else
                            :content="item.content"
                            :role="item.role"
                            :isMarkdown="item.isMarkdown"
                            :typing="item.typing"
                            :showLoading="item.showLoading"
                            theme="text-tool"
                            @onFinish="onFinish(item.id)"
                        >
                            <template #footer>
                                <div class="message-time assistant-time">
                                {{ convertUtcToLocal(item.createTime) }}
                                </div>
                            </template>
                        </msg-item-text>
                    </div>
                </div>
            </div>

            <!-- 底部占位符，用于滚动定位 -->
            <div ref="lastMsgRef" class="last-msg-ref-full-width"></div>
        </div>

        <!-- 输入框区域 -->
        <div v-if="currentModel" class="chat-input-area">
            <Sender
                ref="senderRef"
                v-model="inputMessage"
                variant="updown"
                :auto-size="{ minRows: 2, maxRows: 6 }"
                :clearable="false"
                :allow-speech="false"
                :show-updown="true"
                :input-style="inputStyle"
                :placeholder="t('howCanIHelp')"
                @submit="handleSendMessage"
                class="view-input"
            >
                <!-- 输入框右侧图标 -->
                <template #action-list>
                    <div class="action-list-container">
                        <l-dropdown
                            ref="modelDropdownRef"
                            :type="MODEL_CAPABILITIES.TEXT"
                            :initialSelected="currentModel"
                            @update:selected="onModelSelected"
                            trigger="click"
                            placement="bottom"
                        >
                            <div class="chooise-action">
                                <span>{{ currentModel }}</span>
                            </div>
                        </l-dropdown>
                        <l-send-button
                            :is-can-send="inputMessage.trim() != ''"
                            :is-loading="sendingMessage"
                            :is-chat="true"
                            @onClickSend="handleSendMessage"
                            @onClickStop="handleStopSending"
                        />
                    </div>
                </template>
            </Sender>
        </div>
    </div>
</template>

<script setup>
import { ref, computed, watch, nextTick, onUnmounted } from "vue";
import { Sender } from 'vue-element-plus-x'
import { useI18n } from "vue-i18n";
import { ElMessage } from "element-plus";
import { ApiTextTool } from "@/api/api-text-tool";
import {
    MSG_ROLE_USER,
    MSG_ROLE_ASSISTANT,
    MESSAGE_STATUS,
    onSendParseMsg,
    onAIParseMsg,
} from "@/types/msg";
import MsgItemText from "@/views/alien/components/msg-item-text.vue";
import MessageRetry from "@/components/message/retry.vue";
import LImg from "@/components/l-img.vue";
import { useSmoothScroll, convertUtcToLocal } from "@/utils/util";
import { convertStyleObject } from "@/utils/px-to-rem";
import LDropdown from "@/components/l-dropdown.vue";
import LSendButton from "@/components/l-send-button.vue";
import { MODEL_CAPABILITIES } from '@/models/chat-model-models';

const { t } = useI18n();
const { smoothScrollToRef } = useSmoothScroll();
const modelDropdownRef = ref(null);
// Props
const props = defineProps({
    // 当前模型
    currentModel: {
        type: String,
        default: ''
    },
    selectedTool: {
        type: Object,
        default: null,
    },
    selectedSession: {
        type: Object,
        default: null,
    },
});

// Emits
const emit = defineEmits(["session-created", "session-updated", "model-selected", "message-update-num"]);

// 响应式数据
const messageList = ref([]);
const inputMessage = ref("");
const sendingMessage = ref(false);
const loadingMessages = ref(false);
const hasMoreMessages = ref(true);
const messagesCursor = ref(null);
const streamConnection = ref(null); // 流式连接引用
const senderRef = ref(null); // Sender组件引用
const requestCompleted = ref(false); // 请求完成状态标志
const currentAiMessageId = ref(null); // 当前正在处理的AI消息ID

// DOM引用
const msgListRef = ref(null);
// const lastMsgRef = ref(null); // 已不再使用，保留DOM元素作为滚动锚点

// 自动滚动控制
const autoScroll = ref(true);
const lastScrollTop = ref(0);
const loadingType = ref('none'); // 'none' | 'initial' | 'more'
const isAutoScrolling = ref(false); // 标记是否正在自动滚动
const scrollDebounceFrame = ref(null); // 滚动防抖帧ID
const contentObserver = ref(null); // 内容变化观察器

// 输入框样式
const inputStyle = computed(() => {
    const rawStyle = {
        color: "var(--text-title)",
        "font-size": "16px",
        "min-height": "50px !important",
        padding: "0",
        border: "none",
        "box-shadow": "none",
        "background-color": "transparent",
        "margin-bottom": "12px",
    };
    return convertStyleObject(rawStyle);
});

const showMessageAreaLoading = computed(() => {
    return !props.selectedSession?.isNew && loadingType.value === 'initial';
});


// 滚动处理
const handleScroll = (e) => {
    const el = e.target;
    const currentScrollTop = el.scrollTop;
    const scrollHeight = el.scrollHeight;
    const clientHeight = el.clientHeight;

    // 判断是否滚动到底部（允许15px的误差，确保能正确检测到底部）
    const isAtBottom = scrollHeight - (currentScrollTop + clientHeight) <= 50;

    // 如果正在自动滚动，只处理底部检测，不处理其他逻辑
    if (isAutoScrolling.value) {
        // 即使在自动滚动期间，也要检测是否到达底部
        if (isAtBottom) {
            autoScroll.value = true;
        }
        return;
    }

    // 计算滚动方向
    const isScrollingUp = currentScrollTop < lastScrollTop.value;

    // 计算滚动方向
    const isScrollingDown = currentScrollTop > lastScrollTop.value;

    // 用户手动滚动逻辑
    if (isScrollingUp) {
        // 用户向上滚动，禁用自动滚动
        if (autoScroll.value) {
            autoScroll.value = false;
        }
    } else if (isScrollingDown || isAtBottom) {
        // 用户向下滚动或到达底部，检查是否应该启用自动滚动
        if (isAtBottom && !autoScroll.value) {
            autoScroll.value = true;
        }
    }

    // 检查是否向上滚动且接近顶部，加载更多消息
    const SCROLL_THRESHOLD = 50;
    if (
        isScrollingUp &&
        currentScrollTop <= SCROLL_THRESHOLD &&
        !loadingMessages.value &&
        hasMoreMessages.value
    ) {
        loadMoreMessages();
    }

    // 更新上次滚动位置
    if (!loadingMessages.value) {
        lastScrollTop.value = currentScrollTop;
    }
};

// 滚动到底部
const scrollToBottom = async () => {
    if (!autoScroll.value || !msgListRef.value) return;

    // 标记正在自动滚动
    isAutoScrolling.value = true;

    try {
        const scrollElement = msgListRef.value;
        
        // 使用MutationObserver监听DOM变化，确保Bubble组件内容变化后能正确滚动
        const scrollToBottomWithObserver = () => {
            return new Promise(resolve => {
                let scrollAttempts = 0;
                const maxAttempts = 3;
                
                const performScroll = () => {
                    const currentHeight = scrollElement.scrollHeight;
                    scrollElement.scrollTop = currentHeight;
                    
                    scrollAttempts++;
                    
                    // 使用requestAnimationFrame检查是否需要再次滚动
                    requestAnimationFrame(() => {
                        const newHeight = scrollElement.scrollHeight;
                        
                        // 如果高度还在变化且未达到最大尝试次数，继续滚动
                        if (newHeight > currentHeight && scrollAttempts < maxAttempts) {
                            performScroll();
                        } else {
                            // 最终确保滚动到底部
                            scrollElement.scrollTop = scrollElement.scrollHeight;
                            isAutoScrolling.value = false;
                            resolve();
                        }
                    });
                };
                
                performScroll();
            });
        };
        
        await scrollToBottomWithObserver();
    } catch (error) {
        console.error('Scroll error:', error);
        isAutoScrolling.value = false;
    }
};

// 加载消息列表
const loadMessageList = async (loadMore = false) => {
    if (!props.selectedSession) return;

    // 如果是新会话，不需要加载消息
    if (props.selectedSession.isNew) {
        messageList.value = [];
        hasMoreMessages.value = false;
        return;
    }

    try {
        loadingMessages.value = true;

        // 记录滚动位置（仅在加载更多时需要）
        let oldScrollHeight = 0;
        if (!loadMore && msgListRef.value) {
            oldScrollHeight = msgListRef.value.scrollHeight;
            loadingType.value = 'initial';
        } else {
            loadingType.value = 'more';
        }

        const params = {
            session_id: props.selectedSession.id,
            page_size: 20,
            cursor: loadMore ? messagesCursor.value : null,
        };

        const response = await ApiTextTool.getToolMessageList(params);
        const { items, has_more } = response.data;

        // 转换数据格式
        const formattedMessages = items.map((item) => {
            if (item.message_type === MSG_ROLE_USER) {
                return {
                    ...onSendParseMsg(item),
                    created_at: item.created_at,
                    createTime: item.created_at,
                    messageStatus: MESSAGE_STATUS.SUCCESS, // 历史用户消息默认为成功状态
                };
            } else {
                return {
                    ...onAIParseMsg(item, false),
                    created_at: item.created_at,
                    createTime: item.created_at,
                    messageStatus: MESSAGE_STATUS.SUCCESS, // 历史AI消息默认为成功状态
                };
            }
        });

        if (loadMore) {
            // 加载更多时添加到顶部
            messageList.value = [
                ...formattedMessages.reverse(),
                ...messageList.value,
            ];

            // 保持滚动位置
            nextTick(() => {
                if (msgListRef.value) {
                    const newScrollHeight = msgListRef.value.scrollHeight;
                    msgListRef.value.scrollTop =
                        newScrollHeight - oldScrollHeight;
                }
            });
        } else {
            // 初始加载时替换消息列表
            messageList.value = formattedMessages.reverse();

            // 滚动到底部
            nextTick(() => {
                scrollToBottom();
            });
        }

        hasMoreMessages.value = has_more;
        if (items.length > 0) {
            messagesCursor.value = items[items.length - 1].id;
        }
    } catch (error) {
        console.error("Failed to load message list:", error);
        ElMessage.error(t("failedToLoadMessages"));
    } finally {
        loadingMessages.value = false;
        loadingType.value = 'none';
    }
};

// 加载更多消息
const loadMoreMessages = () => {
    if (hasMoreMessages.value && !loadingMessages.value) {
        loadMessageList(true);
    }
};

// 发送消息
const handleSendMessage = async () => {
    const messageContent = inputMessage.value.trim();
    if (!messageContent || !props.selectedTool || sendingMessage.value) return;

    try {
        sendingMessage.value = true;

        // 清空输入框
        inputMessage.value = "";

        // 添加用户消息到列表
        const currentTime = new Date().toISOString();
        const userMessageData = {
            id: `user_${Date.now()}`,
            role: MSG_ROLE_USER,
            content: messageContent,
            created_at: currentTime,
            message_type: MSG_ROLE_USER,
        };
        const userMessage = onSendParseMsg(userMessageData);
        // 手动添加时间字段和状态
        userMessage.createTime = currentTime;
        userMessage.created_at = currentTime;
        userMessage.messageStatus = MESSAGE_STATUS.SUCCESS; // 用户消息总是成功
        messageList.value.push(userMessage);

        // 立即更新会话的最后一条消息内容（用户消息）
        if (!props.selectedSession?.isNew) {
            emit("session-updated", {
                tool_id: props.selectedTool.id,
                session_id: props.selectedSession.id,
                user_message: messageContent,
                last_message_content: messageContent,
                last_message_time: currentTime,
            });
            emit("message-update-num", {
                sessionId: props.selectedSession.id,
                num: 1
            });
        }

        // 添加AI消息占位符
        const aiMessageId = `ai_${Date.now()}`;
        const aiMessageData = {
            id: aiMessageId,
            role: MSG_ROLE_ASSISTANT,
            content: "",
            created_at: currentTime,
            message_type: MSG_ROLE_ASSISTANT,
        };
        const aiMessage = onAIParseMsg(aiMessageData, true);
        // 手动添加时间字段和状态管理
        aiMessage.createTime = currentTime;
        aiMessage.created_at = currentTime;
        aiMessage.messageStatus = MESSAGE_STATUS.SENDING;
        aiMessage.originalParams = {
            content: messageContent,
            model: props.currentModel,
            toolId: props.selectedTool.id,
            sessionId: props.selectedSession?.isNew ? null : props.selectedSession?.id
        };
        messageList.value.push(aiMessage);

        // 启用自动滚动并滚动到底部
        autoScroll.value = true;
        await nextTick();
        await scrollToBottom();

        // 发送流式消息
        sendStreamMessage(messageContent, aiMessageId);
    } catch (error) {
        console.error("Failed to send message:", error);
        ElMessage.error(t("failedToSendMessage"));

        // 移除失败的消息
        messageList.value = messageList.value.filter(
            (msg) => !msg.id.startsWith("user_") && !msg.id.startsWith("ai_")
        );
        sendingMessage.value = false;
    }
};

// 发送流式消息
const sendStreamMessage = (content, aiMessageId, customParams = null) => {
    // 先关闭之前的连接（如果存在）
    if (streamConnection.value) {
        streamConnection.value.close();
        streamConnection.value = null;
    }

    // 重置请求完成状态并记录当前AI消息ID
    requestCompleted.value = false;
    currentAiMessageId.value = aiMessageId;

    // 用于累积完整的响应
    let fullResponse = "";

    // 准备发送消息的参数
    let chatParams;
    
    if (customParams) {
        // 使用重试时传入的自定义参数
        chatParams = customParams;
    } else {
        // 使用正常发送的参数
        chatParams = {
            tool_id: parseInt(props.selectedTool.id),
            content: content,
            model: props.currentModel // model参数必填，不使用默认值
        };

        // 如果不是新会话，添加session_id
        if (props.selectedSession && !props.selectedSession.isNew) {
            chatParams.session_id = String(props.selectedSession.id); // 确保是字符串类型
        }
    }

    // 使用流式消息API并保存连接对象
    streamConnection.value = ApiTextTool.streamChat(
        chatParams,
        (streamData) => {
            // 处理流式消息片段
            const aiMessageIndex = messageList.value.findIndex(
                (msg) => msg.id === aiMessageId
            );
            if (aiMessageIndex !== -1) {
                // 获取当前消息
                const currentMessage = messageList.value[aiMessageIndex];

                // 获取内容
                const newContent = streamData.content || "";

                // 累积完整响应
                fullResponse += newContent;

                // 创建新的消息对象确保响应式更新
                const updatedMessage = {
                    ...currentMessage,
                    content: fullResponse, // 使用累积的完整内容
                    typing: {
                        step:6,
                    },
                    showLoading: false,
                                            messageStatus: MESSAGE_STATUS.SUCCESS, // 更新状态为成功
                    // 确保保留时间字段
                    createTime: currentMessage.createTime,
                    created_at: currentMessage.created_at,
                };

                // 替换整个消息对象触发响应式更新
                messageList.value[aiMessageIndex] = updatedMessage;

                // 实时更新会话的最后一条消息内容（AI流式响应）
                if (!props.selectedSession?.isNew) {
                    emit("session-updated", {
                        tool_id: props.selectedTool.id,
                        session_id: props.selectedSession.id,
                        user_message: content,
                        last_message_content: fullResponse,
                        last_message_time: currentMessage.created_at,
                    });
                }

                // 内容变化会被MutationObserver自动检测并触发滚动
                // 这里不需要手动调用滚动，避免与观察器冲突
            }
        },
        (error) => {
            // 处理错误
            console.error("Stream chat error:", error);

            // 弹出错误提示
            ElMessage.error(t("failedToSendMessage"));

            // 标记AI消息为失败状态，而不是删除
            if (currentAiMessageId.value) {
                const aiMessageIndex = messageList.value.findIndex(
                    (msg) => msg.id === currentAiMessageId.value
                );
                if (aiMessageIndex !== -1) {
                    messageList.value[aiMessageIndex] = {
                        ...messageList.value[aiMessageIndex],
                        messageStatus: MESSAGE_STATUS.FAILED,
                        typing: false,
                        showLoading: false
                    };
                }
            }

            // 设置请求完成状态和发送按钮状态
            requestCompleted.value = true;
            sendingMessage.value = false; // 错误时直接重置发送按钮状态
            currentAiMessageId.value = null; // 清空当前消息ID

            // 清除连接引用
            streamConnection.value = null;
        },
        (endData) => {
            // 流式响应结束回调
            requestCompleted.value = true;

            // 清除连接引用
            streamConnection.value = null;

            // 获取当前AI消息内容作为最后一条消息
            const aiMessage = messageList.value.find(msg => msg.id === aiMessageId);
            const lastMessageContent = aiMessage ? aiMessage.content : content;
            const currentTime = new Date().toISOString();

            // 触发会话相关事件，通知父组件刷新会话列表
            if (props.selectedSession?.isNew) {
                // 如果是新会话，触发session-created事件
                // 会话列表按时间排序，新创建的会话会在第一个位置
                emit("session-created", {
                    tool_id: props.selectedTool.id,
                    user_message: content,
                    last_message_content: lastMessageContent,
                    last_message_time: currentTime,
                });
            } else {
                console.log('endData',endData)
                // 如果是现有会话，触发session-updated事件
                emit("session-updated", {
                    tool_id: props.selectedTool.id,
                    session_id: props.selectedSession.id,
                    user_message: content,
                    last_message_content: lastMessageContent,
                    last_message_time: currentTime,
                    message_count: props.selectedSession.message_count + 1,
                });
                emit("message-update-num", {
                    sessionId: props.selectedSession.id,
                    num: 1
                });
                nextTick(() => {
                    sendingMessage.value = false;
                })
            }
        }
    );
};

// 消息打字完成回调
const onFinish = (id) => {
    // 查找完成打字的消息
    const finishedMessage = messageList.value.find(msg => msg.id === id);

    // 只处理AI消息的打字完成
    if (finishedMessage && finishedMessage.role === MSG_ROLE_ASSISTANT) {
        // 打字机效果完成后，确保消息状态正确
        const messageIndex = messageList.value.findIndex(msg => msg.id === id);
        if (messageIndex !== -1) {
            const currentMessage = messageList.value[messageIndex];
            const updatedMessage = {
                ...currentMessage,
                typing: false,
                showLoading: false,
                messageStatus: currentMessage.messageStatus || MESSAGE_STATUS.SUCCESS, // 保持原有状态或设为成功
                // 确保保留时间字段和内容
                createTime: currentMessage.createTime,
                created_at: currentMessage.created_at,
            };

            // 替换整个消息对象触发响应式更新
            messageList.value[messageIndex] = updatedMessage;
        }

        // 检查是否是当前正在处理的AI消息且流式响应已完成
        if (id === currentAiMessageId.value && requestCompleted.value) {
            // 流式响应已结束且打字机效果也完成，现在可以重置发送按钮状态
            sendingMessage.value = false;
            currentAiMessageId.value = null; // 清空当前消息ID
        }

        console.log(`Message ${id} typing animation finished`);
    }
};

// 设置内容变化观察器
const setupContentObserver = () => {
    if (!msgListRef.value) return;
    
    // 清理之前的观察器
    if (contentObserver.value) {
        contentObserver.value.disconnect();
    }
    
    // 创建新的观察器
    contentObserver.value = new MutationObserver((mutations) => {
        // 只有在自动滚动启用且不是用户手动滚动时才响应内容变化
        if (!autoScroll.value || isAutoScrolling.value) return;
        
        let shouldScroll = false;
        
        mutations.forEach((mutation) => {
            // 检查是否有子节点变化或文本内容变化
            if (mutation.type === 'childList' || mutation.type === 'characterData') {
                shouldScroll = true;
            }
            // 检查是否有属性变化（可能影响布局）
            if (mutation.type === 'attributes' && 
                (mutation.attributeName === 'style' || mutation.attributeName === 'class')) {
                shouldScroll = true;
            }
        });
        
        if (shouldScroll) {
            // 再次检查是否在底部，只有在底部时才自动滚动
            const scrollElement = msgListRef.value;
            const scrollHeight = scrollElement.scrollHeight;
            const scrollTop = scrollElement.scrollTop;
            const clientHeight = scrollElement.clientHeight;
            const isAtBottom = scrollHeight - (scrollTop + clientHeight) <= 50;
            
            if (isAtBottom) {
                // 清除之前的防抖帧
                if (scrollDebounceFrame.value) {
                    cancelAnimationFrame(scrollDebounceFrame.value);
                }
                
                // 使用requestAnimationFrame进行防抖
                scrollDebounceFrame.value = requestAnimationFrame(() => {
                    nextTick(() => {
                        scrollToBottom();
                    });
                });
            }
        }
    });
    
    // 开始观察消息列表容器的变化
    contentObserver.value.observe(msgListRef.value, {
        childList: true,
        subtree: true,
        characterData: true,
        attributes: true,
        attributeFilter: ['style', 'class']
    });
};

// 监听选中会话变化
watch(
    () => props.selectedSession,
    async (newSession, oldSession) => {
        if (newSession) {
            if (newSession.isNew) {
                // 新会话，清空消息列表
                messageList.value = [];
                hasMoreMessages.value = false;
            } else {
                // 检查是否是从临时会话转换而来的真实会话
                const wasTemporarySession = oldSession?.isNew;
                const hasExistingMessages = messageList.value.length > 0;

                // 如果是从临时会话转换而来的，不管有没有消息都不重新加载
                // 因为：
                // 1. 如果有消息，说明是刚刚发送的对话，保持现有消息
                // 2. 如果没有消息，说明是新创建的会话，也不需要从服务器加载
                if (wasTemporarySession) {
                    console.log('Converting from temporary session, keeping existing messages');
                    return;
                }

                // 只有在用户明确点击选择了一个已存在的会话时才加载消息
                // 这种情况下 oldSession 不会是临时会话
                console.log('Loading messages for selected existing session');
                loadMessageList();
            }
        } else {
            messageList.value = [];
        }
        inputMessage.value = '';
        
        // 设置内容观察器
        await nextTick(() => {
            setupContentObserver();
            modelDropdownRef?.value?.handleSelectItem(props.selectedSession.ai_model);
        });
    },
    { immediate: true }
);

// 新的模型选择事件处理
const onModelSelected = (modelName) => {
    emit('model-selected', modelName);
};


// 处理消息重试
const handleRetryMessage = async (messageId) => {
    const messageIndex = messageList.value.findIndex(msg => msg.id === messageId);
    if (messageIndex === -1) return;
    
    const message = messageList.value[messageIndex];
    if (!message.originalParams || message.role !== MSG_ROLE_ASSISTANT) return;
    
    try {
        sendingMessage.value = true;
        
        // 更新消息状态为发送中
        messageList.value[messageIndex] = {
            ...messageList.value[messageIndex],
            messageStatus: MESSAGE_STATUS.SENDING,
            content: '',
            typing: { step: 6 },
            showLoading: true
        };
        
        // 重新发送流式消息
        currentAiMessageId.value = messageId;
        
        // 准备重试参数
        const retryParams = {
            tool_id: parseInt(message.originalParams.toolId),
            content: message.originalParams.content,
            model: message.originalParams.model
        };
        
        // 如果有会话ID，添加到参数中
        if (message.originalParams.sessionId) {
            retryParams.session_id = String(message.originalParams.sessionId);
        }
        
        // 重新发送流式消息
        sendStreamMessage(message.originalParams.content, messageId, retryParams);
        
    } catch (error) {
        console.error('Failed to retry message:', error);
        
        // 重试失败，保持失败状态
        messageList.value[messageIndex] = {
            ...messageList.value[messageIndex],
            messageStatus: MESSAGE_STATUS.FAILED,
            typing: false,
            showLoading: false
        };
        
        ElMessage.error(t("failedToSendMessage"));
        sendingMessage.value = false;
        currentAiMessageId.value = null;
    }
};

// 停止发送处理
const handleStopSending = () => {
    if (streamConnection.value) {
        streamConnection.value.close();
        streamConnection.value = null;
    }

    // 清除滚动防抖帧
    if (scrollDebounceFrame.value) {
        cancelAnimationFrame(scrollDebounceFrame.value);
        scrollDebounceFrame.value = null;
    }

    // 重置自动滚动状态
    isAutoScrolling.value = false;

    // 设置请求完成状态为true，以便onFinish可以处理
    requestCompleted.value = true;

    // 停止所有正在打字的AI消息
    messageList.value.forEach((message, index) => {
        if (message.role === MSG_ROLE_ASSISTANT && (message.typing || message.showLoading)) {
            // 创建新的消息对象以触发响应式更新
            const updatedMessage = {
                ...message,
                typing: false,
                showLoading: false,
                messageStatus: message.messageStatus || MESSAGE_STATUS.SUCCESS, // 保持原有状态或设为成功
                // 确保保留时间字段
                createTime: message.createTime,
                created_at: message.created_at,
            };

            // 替换整个消息对象触发响应式更新
            messageList.value[index] = updatedMessage;
        }
    });

    // 由于主动停止，可以直接修改发送按钮状态
    sendingMessage.value = false;
    currentAiMessageId.value = null; // 清空当前消息ID
};

// 组件销毁时清理资源
onUnmounted(() => {
    if (scrollDebounceFrame.value) {
        cancelAnimationFrame(scrollDebounceFrame.value);
        scrollDebounceFrame.value = null;
    }
    
    if (contentObserver.value) {
        contentObserver.value.disconnect();
        contentObserver.value = null;
    }
    
    if (streamConnection.value) {
        streamConnection.value.close();
        streamConnection.value = null;
    }
});

// 导出方法供父组件使用
defineExpose({
    loadMessageList,
    clearMessages: () => {
        messageList.value = [];
        loadingType.value = 'none';
        // 清理滚动相关状态
        if (scrollDebounceFrame.value) {
            cancelAnimationFrame(scrollDebounceFrame.value);
            scrollDebounceFrame.value = null;
        }
        if (contentObserver.value) {
            contentObserver.value.disconnect();
            contentObserver.value = null;
        }
        isAutoScrolling.value = false;
    },
});
</script>

