<template>
    <div class="text-tool-page" :style="pageStyle">
        <!-- 左侧工具列表区域 - 使用character-sidebar组件 -->
        <character-sidebar :title="t('textTool')" :selectedItem="selectedTool" :loadItemsApi="loadToolListApi"
            :createButtonText="t('createCharacter')" :previewLabel="'Prompt'"
            :statsIcon="'/static/images/chat_icon.png'" :emptyText="t('noTool')" @select="handleToolSelect"
            @create="clickCreateTool" @showDetails="handleToolDetails" ref="toolSidebarRef" />

        <!-- 第一个分割线 -->
        <ResizableDivider divider-type="first" :left-min-width="200" :left-max-width="600" :right-min-width="200"
            :right-max-width="600" @resize="handleFirstDividerResize" />

        <!-- 中间会话列表区域 - 使用chat-sidebar组件 -->
        <chat-sidebar :selectedCharacter="selectedTool" :selectedSession="selectedSession" :chatSessions="sessionList"
            :pagination="sessionPagination" :modelType="MODEL_CAPABILITIES.TEXT" @selectSession="clickSelectSession"
            @createNewChat="clickNewChat" @editRemark="openRemarkDialog" @shareSession="handleShareSession"
            @deleteSession="confirmDeleteSession" @scroll="handleChatListScroll" @filter-change="handleFilterChange" />

        <!-- 第二个分割线 -->
        <ResizableDivider divider-type="second" :left-min-width="200" :left-max-width="600" :right-min-width="200"
            :right-max-width="600" @resize="handleSecondDividerResize" />

        <!-- 中央聊天界面 -->
        <div class="chat-interface-section">
            <div v-if="!selectedSession" class="empty-chat-state">
                <div class="empty-content">
                    <p>{{ t("toolSelectOrStartNew") }}</p>
                </div>
            </div>

            <div v-else class="chat-interface">
                <!-- 聊天标题栏 -->
                <div class="chat-header">
                    <div class="chat-title-info" :style="{width:chatTitleInfoWidth}">
                        <h2 class="chat-title">{{ getChatTitle() }}</h2>
                        <div class="chat-subtitle">
                            <span>{{
                                t("startedOn", {
                                date: convertUtcToLocal(
                                selectedSession.created_at,
                                DATE_FORMATS.US_DATE
                                ),
                                })
                                }}</span>
                            <span v-if="selectedSession.remark" class="separator">|</span>
                            <span v-if="selectedSession.remark" class="session-remark">
                                {{ t('remark') }}: {{ selectedSession.remark }}
                            </span>
                        </div>
                    </div>
                    <div class="header-actions" ref="headerActionsRef">
                        <div class="action-btn">
                            <l-img src="/static/images/share_icon.png" w="20px" h="20px" />
                        </div>
                        <div class="action-btn" @click="showCurrentToolPrompt">
                            <l-img src="/static/images/cmd_icon.png" w="20px" h="20px" />
                        </div>
                    </div>
                </div>

                <!-- 对话框组件 -->
                <chat-dialog :selected-tool="selectedTool" :selected-session="selectedSession"
                    :current-model="currentModel" @session-created="handleSessionCreated"
                    @session-updated="handleSessionUpdated" @message-update-num="handleMessageUpdateNum" 
                    @model-selected="onModelSelected" />
            </div>
        </div>

        <!-- 创建工具弹窗 -->
        <create-tool v-model:visible="createToolVisible" :edit-data="editToolData" @create="handleToolCreated" />

        <!-- 工具详情弹窗 -->
        <prompt-view v-model:visible="promptViewVisible" :prompt="selectedPrompt" :detail-data="toolDetailData"
            :loading="isLoadingToolDetail" @load-detail="handleLoadToolDetail" @delete="handleToolDeleted"
            @edit="handleEdit" />

        <!-- 备注弹窗 -->
        <remark-dialog v-model:visible="remarkDialogVisible" :initial-value="remarkText" :max-length="120"
            @save="handleSaveRemark" @cancel="remarkDialogVisible = false" />

        <!-- 删除确认对话框 -->
        <session-delete-dialog v-model:visible="deleteConfirmVisible" :session="sessionToDelete"
            @confirm="handleDeleteSession" @cancel="deleteConfirmVisible = false" />
    </div>
</template>

<script setup>
import { ref, computed, watch } from "vue";
import { useI18n } from "vue-i18n";
import LImg from "@/components/l-img.vue";
import CharacterSidebar from "@/components/ai-chat-tool/character-sidebar.vue";
import ChatSidebar from "@/components/ai-chat-tool/chat-sidebar.vue";
import ResizableDivider from "@/components/business/resizable-divider.vue";
import PromptView from "@/components/dialog/prompt-view.vue";
import CreateTool from "@/components/ai-chat-tool/create-tool.vue";
import ChatDialog from "@/components/ai-chat-tool/chat.vue";
import RemarkDialog from "@/components/dialog/remark-dialog.vue";
import SessionDeleteDialog from "@/components/dialog/session-delete-dialog.vue";
import { ApiTextTool } from "@/api/api-text-tool";
import { useUserStore } from "@/store/modules/user";
import { MODEL_CAPABILITIES } from '@/models/chat-model-models';
import { useResizablePanels } from '@/composables/useResizablePanels';
import { convertUtcToLocal } from '@/utils/util';
import { DATE_FORMATS } from '@/types/date';
import { validateAndSetAIModel } from '@/utils/ai-model-validator';
import pxToRem from "@/utils/px-to-rem";

const { t } = useI18n();
const userStore = useUserStore();

// 使用拖拽面板功能
const {
    leftPanelWidth: toolSidebarWidth,
    rightPanelWidth: chatSidebarWidth,
    pageStyle,
    handleFirstDividerResize,
    handleSecondDividerResize
} = useResizablePanels({
    leftPanel: {
        defaultPercent: 20,
        defaultPixels: 300, // 默认300px宽度
        minPixels: 200,
        maxPixels: 600
    },
    rightPanel: {
        defaultPercent: 20,
        defaultPixels: 300, // 默认300px宽度
        minPixels: 200,
        maxPixels: 600
    },
    storageKey: 'text-tool-panels'
});

// 从userStore获取用户名称的计算属性
const userName = computed(() => {
    const currentUser = userStore.currentUser;
    return currentUser?.nickname || t("defaultUser");
});

// 响应式数据
const sessionList = ref([]);
const currentModel = ref('');
const selectedTool = ref(null);
const selectedSession = ref(null);
const selectedPrompt = ref(null);
const headerActionsRef = ref(null);

// 弹窗控制
const createToolVisible = ref(false);
const promptViewVisible = ref(false);
const remarkDialogVisible = ref(false);
const remarkText = ref("");
const currentEditingSession = ref(null);

// 新增：工具详情数据加载相关状态
const toolDetailData = ref(null);
const isLoadingToolDetail = ref(false);

// 新增：编辑工具数据状态
const editToolData = ref(null);

// 加载状态
const loadingSessions = ref(false);

// 分页状态 - 适配chat-sidebar组件期望的格式
const sessionPagination = computed(() => ({
    loading: loadingSessions.value,
    hasMore: hasMoreSessions.value,
    cursor: sessionsCursor.value,
}));
const filterParams = ref({

});

const hasMoreSessions = ref(true);
const sessionsCursor = ref(null);

// 容器引用
const toolSidebarRef = ref(null);

// 确认删除对话框
const deleteConfirmVisible = ref(false);
const sessionToDelete = ref(null);

const chatTitleInfoWidth=computed(()=>{
    return `calc(100% - pxToRem(${headerActionsRef.value?.clientWidth}px - 30px))`;
})

// 监听选中工具变化
watch(selectedTool, (newTool) => {
    if (newTool) {
        loadSessionList();
    } else {
        sessionList.value = [];
        selectedSession.value = null;
    }
});

// 监听创建弹窗状态变化，弹窗关闭时清除编辑数据
watch(createToolVisible, (isVisible) => {
    if (!isVisible) {
        editToolData.value = null;
    }
});

// ===============================
// 工具相关方法 - 适配character-sidebar组件
// ===============================

// API适配函数 - 将原有的API调用适配为组件期望的格式
const loadToolListApi = async (pageSize, cursor) => {
    try {
        const params = {
            tool_type: "text",
            page_size: pageSize,
            cursor: cursor,
        };
        const response = await ApiTextTool.getToolList(params);

        // 转换为组件期望的格式
        return {
            code: 200,
            data: {
                items: response.data.items || [],
                has_more: response.data.has_more || false,
            },
        };
    } catch (error) {
        console.error("Failed to load tool list:", error);
        throw error;
    }
};

// 数据格式化函数 - 将工具数据转换为组件期望的格式
const formatToolForSidebar = (tool) => ({
    id: tool.id,
    title: tool.title,
    description: tool.description,
    preview: getPromptPreview(tool.prompt),
    author: `${tool.creator_name} ${t("at")} ${convertUtcToLocal(tool.created_at)}`,
    stats: formatUsageCount(tool.usage_count),
});

// 处理工具选择事件
const handleToolSelect = (formattedTool) => {
    // 从原始数据中找到对应的工具对象
    const originalTool = toolSidebarRef.value?.characters.find(
        (tool) => tool.id === formattedTool.id
    );
    if(selectedTool.value?.id === originalTool.id) return;
    if (originalTool) {
        selectedTool.value = originalTool;
        selectedSession.value = null;
    }
};

// 处理工具详情查看事件
const handleToolDetails = (formattedTool) => {
    // 从原始数据中找到对应的工具对象
    const originalTool = toolSidebarRef.value?.characters.find(
        (tool) => tool.id === formattedTool.id
    );
    if (originalTool) {
        clickToolMenu(originalTool);
    }
};

const clickCreateTool = () => {
    createToolVisible.value = true;
};

const clickToolMenu = (tool) => {
    selectedPrompt.value = {
        id: tool.id,
        title: t("toolDetails"),
        content: tool.prompt,
        category: tool.title,
        description: tool.description,
        creator: tool.creator_name,
        createdAt: tool.created_at,
        chats: tool.usage_count,
    };

    // 重置详情数据状态
    toolDetailData.value = null;
    isLoadingToolDetail.value = false;

    promptViewVisible.value = true;
};

// 会话相关方法
const loadSessionList = async (loadMore = false) => {
    if (!selectedTool.value) return;

    try {
        loadingSessions.value = true;
        const params = {
            tool_id: selectedTool.value.id,
            page_size: 20,
            cursor: loadMore ? sessionsCursor.value : null,
            model: filterParams.value?.model || null,
        };

        const response = await ApiTextTool.getSessionList(params);
        const { items, has_more } = response.data;

        // 为每个会话设置title为创建人名称
        const processedItems = items.map((session) => ({
            ...session,
            title:
                session.creator_name ||
                selectedTool.value.creator_name ||
                t("unknownCreator"),
            last_message_content: session.last_message_content,
        }));

        if (loadMore) {
            sessionList.value.push(...processedItems);
        } else {
            sessionList.value = processedItems;
        }

        hasMoreSessions.value = has_more;
        if (processedItems.length > 0) {
            sessionsCursor.value = processedItems[processedItems.length - 1].id;
        }
    } catch (error) {
        console.error("Failed to load session list:", error);
    } finally {
        loadingSessions.value = false;
    }
};

const clickNewChat = async (modelName) => {
    if (!selectedTool.value) {
        ElMessage.warning(t("selectToolFirst"));
        return;
    }

    try {
        // 创建一个临时的新会话对象
        const newSession = {
            id: `temp_${Date.now()}`, // 临时ID
            tool_id: selectedTool.value.id,
            user_name: userName.value,
            title: selectedTool.value.creator_name || t("unknownCreator"), // 设置title为创建人名称
            last_message_time: new Date().toISOString(),
            last_message_content: " ",
            message_count: 0,
            created_at: new Date().toISOString(),
            isNew: true, // 标记为新会话
        };
        if (modelName) {
            newSession.ai_model = modelName;
            currentModel.value = modelName;
        }

        // 将新会话添加到列表顶部
        sessionList.value.unshift(newSession);

        // 自动选中新会话
        selectedSession.value = newSession;
        ElMessage.success(t('chatCreated'));
    } catch (error) {
        console.error("Failed to create new chat:", error);
    }
};

const clickSelectSession = async (session) => {
    console.log('User clicked to select session:', session.id);
    selectedSession.value = session;
    await validateAndSetAIModel({
        sessionModel: session.ai_model,
        modelType: 'text',
        currentModelRef: currentModel
    });
};

// 工具栏事件处理
const handleToolCreated = async (newTool) => {
    // 重新加载工具列表
    if (toolSidebarRef.value) {
        await toolSidebarRef.value.loadItems();
    }
};

const handleToolDeleted = async (tool) => {
    try {
        await ApiTextTool.deleteTool({ tool_id: tool.id });

        // 重新加载工具列表
        if (toolSidebarRef.value) {
            await toolSidebarRef.value.loadItems();
        }

        if (selectedTool.value?.id === tool.id) {
            selectedTool.value = null;
        }
        ElMessage.success(t("toolDeleted"));
    } catch (error) {
        console.error("Failed to delete tool:", error);
    }
};

// 工具方法
const getPromptPreview = (prompt) => {
    if (!prompt) return "";
    return prompt.length > 100 ? prompt.substring(0, 100) + "..." : prompt;
};

const formatUsageCount = (count) => {
    if (count >= 1000) {
        return (count / 1000).toFixed(1) + "k";
    }
    return count.toString();
};


const getChatTitle = () => {
    if (!selectedTool.value || !selectedSession.value) return "";
    const sessionUserName = selectedSession.value.user_name || userName.value;
    return `${selectedTool.value.title} - Chat with ${sessionUserName}`;
};

const handleChatListScroll = (event) => {
    if (!hasMoreSessions.value || loadingSessions.value) return;

    const target = event.target;
    const { scrollTop, scrollHeight, clientHeight } = target;

    // 当滚动到底部附近30px时触发加载
    if (scrollTop + clientHeight >= scrollHeight - 30) {
        loadSessionList(true);
    }
};

// 更新当前会话的最后一条消息内容
const updateCurrentSessionMessage = (messageContent, messageTime, sessionId = null) => {
    // 使用传入的sessionId或当前选中会话的ID
    const targetSessionId = sessionId || selectedSession.value?.id;
    if (!targetSessionId) return;

    // 截断过长的消息内容
    const truncatedMessage = messageContent && messageContent.length > 100
        ? messageContent.substring(0, 100) + '...'
        : messageContent;

    // 查找要更新的会话
    const sessionIndex = sessionList.value.findIndex(
        (s) => s.id === targetSessionId
    );

    if (sessionIndex !== -1) {
        // 更新会话信息
        const updatedSession = {
            ...sessionList.value[sessionIndex],
            last_message_content: truncatedMessage,
            last_message_time: messageTime,
        };

        // 更新会话列表中的数据
        sessionList.value[sessionIndex] = updatedSession;

        // 如果当前选中的是这个会话，也更新选中会话的信息
        if (selectedSession.value && selectedSession.value.id === targetSessionId) {
            selectedSession.value.last_message_content = truncatedMessage;
            selectedSession.value.last_message_time = messageTime;
        }

        console.log(`Updated session ${targetSessionId} message content locally`);
    } else {
        console.warn(`Session ${targetSessionId} not found in local list`);
    }
};

// 处理会话创建
const handleSessionCreated = async (sessionData) => {
    try {
        // 检查当前选中的会话是否是临时会话
        const isConvertingTempSession = selectedSession.value?.isNew;

        if (isConvertingTempSession) {
            // 如果是从临时会话转换过来的，需要重新加载会话列表以获取真实的会话ID
            await loadSessionList();

            // 会话列表按时间排序，新创建的会话会在第一个位置
            if (sessionList.value.length > 0) {
                selectedSession.value = sessionList.value[0];
                console.log('Selected newly created session:', selectedSession.value);
            }
        } else {
            // 非临时会话的情况，尝试查找或创建新会话项

            // 首先尝试通过用户消息内容查找匹配的会话（如果已存在）
            const existingSession = sessionList.value.find(
                (s) =>
                    s.tool_id === sessionData.tool_id &&
                    s.last_message_content?.includes(
                        sessionData.user_message?.substring(0, 20) || ""
                    )
            );

            if (existingSession) {
                // 如果找到已存在的会话，选中它
                selectedSession.value = existingSession;
                console.log('Found existing session:', existingSession);
            } else {
                // 如果没有找到，说明是真正的新会话，需要重新加载会话列表
                console.log('New session created, reloading session list...');
                await loadSessionList();

                if (sessionList.value.length > 0) {
                    selectedSession.value = sessionList.value[0];
                }
            }
        }
    } catch (error) {
        console.error("Failed to handle session creation:", error);
        // 出错时回退到重新加载
        try {
            await loadSessionList();
        } catch (reloadError) {
            console.error("Failed to reload session list:", reloadError);
        }
    }
};

const handleMessageUpdateNum = (messageData) => {
    const { sessionId, num } = messageData;
    const index = sessionList.value.findIndex(session => session.id === sessionId);
    let count = 0;
    if(index > -1) {
        count = sessionList.value[index].message_count;
    }
    sessionList.value[index].message_count = count + num;
};

// 处理会话更新 - 在流式响应过程中或结束后调用
const handleSessionUpdated = async (sessionData) => {
    try {

        // 检查当前选中的会话是否是临时会话
        const isConvertingTempSession = selectedSession.value?.isNew;

        if (isConvertingTempSession) {
            // 如果是从临时会话转换过来的，需要重新加载会话列表
            await loadSessionList();

            // 会话列表按时间排序，选中第一个会话
            if (sessionList.value.length > 0) {
                selectedSession.value = sessionList.value[0];
            }
        } else if (selectedSession.value && !selectedSession.value.isNew && sessionData.session_id) {
            // 对于已存在的真实会话，直接更新本地数据
            updateCurrentSessionMessage(sessionData.last_message_content, sessionData.last_message_time, sessionData.session_id);
        }
    } catch (error) {
        console.error("Failed to handle session update:", error);
        // 出错时回退到重新加载
        try {
            await loadSessionList();
        } catch (reloadError) {
            console.error("Failed to reload session list:", reloadError);
        }
    }
};

// 处理带指定模型的新会话创建
const onModelSelected = async (modelName) => {
    let newSessionIndex = sessionList.value.findIndex(session => session.isNew);
    if (currentModel.value && modelName && currentModel.value !== modelName) {
        if (newSessionIndex > -1) {
            sessionList.value[newSessionIndex].ai_model = modelName;
            currentModel.value = modelName;
            if (selectedSession?.value?.id != sessionList.value[newSessionIndex].id) {
                selectedSession.value = sessionList.value[newSessionIndex];
            }
            return;
        }
        clickNewChat(modelName);
    }
    currentModel.value = modelName;
    if (newSessionIndex > -1) {
        sessionList.value[newSessionIndex].ai_model = currentModel.value;
    }
};

const openRemarkDialog = (session) => {
    // 打开备注对话框
    currentEditingSession.value = session;
    remarkText.value = session.remark || "";
    remarkDialogVisible.value = true;
};

const handleSaveRemark = async (value) => {
    if (!currentEditingSession.value) return;

    try {
        // 调用API更新备注
        const response = await ApiTextTool.updateTextToolSessionRemark(String(currentEditingSession.value.id), value);

        if (response && response.code === 200) {
            // 更新本地会话数据
            const sessionIndex = sessionList.value.findIndex(
                (s) => s.id === currentEditingSession.value.id
            );

            if (sessionIndex !== -1) {
                sessionList.value[sessionIndex].remark = value;

                // 如果当前编辑的是选中的会话，也更新选中会话
                if (selectedSession.value?.id === currentEditingSession.value.id) {
                    selectedSession.value.remark = value;
                }
            }

            ElMessage.success(t("remarkUpdated"));
        } else {
            throw new Error('API response error');
        }
    } catch (error) {
        console.error("Failed to update remark:", error);
        ElMessage.error(t('updateError') || 'Failed to update remark');
    }
};

const handleShareSession = (session) => {
    // 分享会话功能（暂不实现具体逻辑）
    ElMessage.info(t("shareFeatureComingSoon"));
};

const confirmDeleteSession = (session) => {
    // 打开删除确认对话框
    sessionToDelete.value = session;
    deleteConfirmVisible.value = true;
};

const handleDeleteSession = async () => {
    if (!sessionToDelete.value) return;

    try {
        // 调用删除会话API
        const response = await ApiTextTool.deleteTextToolSession(String(sessionToDelete.value.id));

        if (response && response.code === 200) {
            // 从列表中移除会话
            const index = sessionList.value.findIndex(s => s.id === sessionToDelete.value.id);
            if (index !== -1) {
                sessionList.value.splice(index, 1);
            }

            // 如果删除的是当前选中的会话，清除选中状态
            if (selectedSession.value?.id === sessionToDelete.value.id) {
                selectedSession.value = null;
            }

            ElMessage.success(t("sessionDeleted"));
        } else {
            throw new Error('API response error');
        }
    } catch (error) {
        console.error("Failed to delete session:", error);
        ElMessage.error(t('deleteError'));
    } finally {
        deleteConfirmVisible.value = false;
        sessionToDelete.value = null;
    }
};

const showCurrentToolPrompt = () => {
    if (!selectedTool.value) {
        ElMessage.warning(t("selectToolFirst"));
        return;
    }

    selectedPrompt.value = {
        id: selectedTool.value.id,
        title: selectedTool.value.title,
        content: selectedTool.value.prompt,
        category: selectedTool.value.title,
        description: selectedTool.value.description,
        creator: selectedTool.value.creator_name,
        createdAt: selectedTool.value.created_at,
        chats: selectedTool.value.usage_count,
    };
    promptViewVisible.value = true;
};

// 新增：处理工具详情数据加载
const handleLoadToolDetail = async (toolId) => {
    // if (!toolId) {
    //     console.warn('No tool ID provided for detail loading');
    //     return;
    // }
    // isLoadingToolDetail.value = true;
    // try {
    //     const response = await ApiTextTool.getToolDetail({ tool_id: toolId });
    //     if (response && response.code === 200 && response.data) {
    //         const {tool}=response.data;
    //         selectedPrompt.value = {
    //     id: tool.id,
    //     title: tool.title,
    //     content: tool.prompt,
    //     category: tool.title,
    //     description: tool.description,
    //     creator: tool.creator_name,
    //     createdAt: tool.created_at,
    //     chats: tool.usage_count,
    // };
    //     } else {
    //         console.warn('Failed to load tool detail:', response);
    //         ElMessage.warning(t('loadError'));
    //     }
    // } catch (error) {
    //     console.error('Error loading tool detail:', error);
    //     ElMessage.error(t('loadError'));
    // } finally {
    //     isLoadingToolDetail.value = false;
    // }
};

const handleEdit = async (toolData) => {
    try {
        // 如果传入的是完整的工具数据对象
        if (toolData && typeof toolData === "object") {
            // 先从侧边栏的工具数组中查找完整的工具数据
            let completeToolData = null;

            if (toolData.id && toolSidebarRef.value?.characters) {
                completeToolData = toolSidebarRef.value.characters.find(
                    (tool) => tool.id === toolData.id
                );
            }

            // 如果找到了完整的工具数据，使用它；否则使用传入的数据
            if (completeToolData) {
                editToolData.value = {
                    id: completeToolData.id,
                    title: completeToolData.title,
                    description: completeToolData.description,
                    prompt: completeToolData.prompt,
                };
            } else {
                // 使用传入的数据
                editToolData.value = {
                    id: toolData.id,
                    title: toolData.title || toolData.name,
                    description: toolData.description,
                    prompt: toolData.prompt || toolData.content,
                };
            }
        }
        promptViewVisible.value = false;
        // 打开创建/编辑弹窗
        createToolVisible.value = true;
    } catch (error) {
        console.error("Failed to handle edit:", error);
        ElMessage.error(t("loadEditDataFailed"));
    }
};

const handleFilterChange = (params) => {
    console.log('Text tool filter changed:', params);
    filterParams.value.model = params.modelName;

    // 根据筛选参数重新加载会话列表
    if (selectedTool.value) {
        // 重置分页状态
        sessionsCursor.value = null;
        hasMoreSessions.value = true;

        // 重新加载会话列表
        loadSessionList(false);
    }
};
</script>

