/**
 * 文字工具相关API服务
 * 提供文字工具的列表、创建、使用、会话管理等功能
 */
import { ApiClient } from './client-api';
import { ApiResponse } from './definitions';
import {
    API_TEXT_TOOL_LIST,
    API_TEXT_TOOL_CHAT,
    API_TEXT_TOOL_SESSIONS,
    API_TEXT_TOOL_CREATE,
    API_TEXT_TOOL_DETAIL,
    API_TEXT_TOOL_DELETE,
    API_TEXT_TOOL_MESSAGES,
    API_TEXT_TOOL_SESSION_DELETE,
    API_TEXT_TOOL_SESSION_REMARK
} from './api-url';
import {
    ToolListResponse,
    ToolUseResponse,
    ToolSessionListResponse,
    ToolInfo,
    ToolDetailResponse,
    ToolDeleteResponse,
    ToolMessageListResponse,
    ToolSessionDeleteResponseInfo,
    ToolListParams,
    ToolUseParams,
    ToolCreateParams,
    ToolSessionListParams,
    ToolMessageListParams,
    ToolSessionDeleteParams,
    StreamMessageCallback,
    StreamErrorCallback,
    StreamEndCallback,
    StreamController,
} from '../models/tool-models';
import { GenericResponseData} from '../models/base-models';
import { getAccessToken } from '../utils/auth';

/**
 * 文字工具API服务类
 * 集中管理所有文字工具相关的API调用
 */
export class ApiTextTool {
    /**
     * 获取文字工具列表
     * @param params 请求参数
     * @returns 文字工具列表
     */
    static async getToolList(params: ToolListParams = {}): Promise<ApiResponse<ToolListResponse>> {
        return await ApiClient.post(
            API_TEXT_TOOL_LIST,
            {
                tool_type: 'text',
                page_size: 20,
                cursor: null,
                ...params
            },
            ToolListResponse
        );
    }

    /**
     * 创建文字工具
     * @param params 创建参数
     * @returns 创建的工具信息
     */
    static async createTool(params: ToolCreateParams): Promise<ApiResponse<ToolInfo>> {
        return await ApiClient.post(
            API_TEXT_TOOL_CREATE,
            params,
            ToolInfo
        );
    }

    /**
     * 获取文字工具详情
     * @param params 请求参数
     * @returns 工具详情
     */
    static async getToolDetail(params: { tool_id: number }): Promise<ApiResponse<ToolDetailResponse>> {
        return await ApiClient.post(
            API_TEXT_TOOL_DETAIL,
            params,
            ToolDetailResponse
        );
    }

    /**
     * 删除文字工具
     * @param params 删除参数
     * @returns 删除结果
     */
    static async deleteTool(params: { tool_id: number }): Promise<ApiResponse<ToolDeleteResponse>> {
        return await ApiClient.post(
            API_TEXT_TOOL_DELETE,
            params,
            ToolDeleteResponse
        );
    }

    /**
     * 获取文字工具会话列表
     * @param params 请求参数
     * @returns 会话列表
     */
    static async getSessionList(params: ToolSessionListParams): Promise<ApiResponse<ToolSessionListResponse>> {
        return await ApiClient.post(
            API_TEXT_TOOL_SESSIONS,
            {
                page_size: 20,
                cursor: null,
                ...params
            },
            ToolSessionListResponse
        );
    }

    /**
     * 获取文字工具消息列表
     * @param params 请求参数
     * @returns 消息列表
     */
    static async getToolMessageList(params: ToolMessageListParams): Promise<ApiResponse<ToolMessageListResponse>> {
        return await ApiClient.post(
            API_TEXT_TOOL_MESSAGES,
            {
                page_size: 20,
                cursor: null,
                ...params
            },
            ToolMessageListResponse
        );
    }

    /**
     * 删除文字工具会话
     * @param session_id 会话ID
     * @returns 删除结果
     */
    static async deleteTextToolSession(session_id: string): Promise<ApiResponse<ToolSessionDeleteResponseInfo>> {
        return await ApiClient.post(
            API_TEXT_TOOL_SESSION_DELETE,
            { id: session_id },
            ToolSessionDeleteResponseInfo
        );
    }

    /**
     * 更新文本工具会话备注
     * @param params 备注更新参数
     * @returns 更新结果
     */
    static async updateTextToolSessionRemark(id: string, remark: string): Promise<ApiResponse<GenericResponseData>> {
        return await ApiClient.post(
            API_TEXT_TOOL_SESSION_REMARK,
            { id, remark }, 
            GenericResponseData
        );
    }

    /**
     * 流式发送文字工具消息
     * @param params 消息参数
     * @param onMessage 接收流式消息的回调函数
     * @param onError 错误处理回调函数
     * @param onEnd 流结束时的回调函数
     * @returns 返回一个包含close方法的对象，用于取消请求
     */
    static streamChat(
        params: ToolUseParams,
        onMessage: StreamMessageCallback,
        onError?: StreamErrorCallback,
        onEnd?: StreamEndCallback
    ): StreamController {
        // 构建URL和请求参数
        const baseURL = (process.env.VITE_BASE_URL || '') + (process.env.VITE_API_URL || '');
        const token = getAccessToken();
        const url = baseURL + API_TEXT_TOOL_CHAT

        // 创建AbortController用于取消请求
        const controller = new AbortController();
        const { signal } = controller;

        // 发起fetch请求
        fetch(url, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${token}`,
            },
            body: JSON.stringify(params),
            signal,
        })
        .then(response => {
            if (!response.ok) {
                throw new Error(`HTTP error! Status: ${response.status}`);
            }

            // 获取响应的reader
            const reader = response.body?.getReader();
            if (!reader) {
                throw new Error('Failed to get response reader');
            }

            const decoder = new TextDecoder('utf-8');
            let buffer = ''; // 用于存储不完整的消息片段
            let accumulatedText = ''; // 用于累积所有文本

            // 处理数据流
            const processStream = async (): Promise<void> => {
                try {
                    while (true) {
                        const { done, value } = await reader.read();

                        if (done) {
                            // 处理缓冲区中可能剩余的数据
                            if (buffer.trim()) {
                                processBufferContent(buffer);
                            }

                            // 流结束
                            if (onEnd) onEnd({ content: accumulatedText });
                            break;
                        }

                        // 解码二进制数据
                        const chunk = decoder.decode(value, { stream: true });
                        buffer += chunk;

                        // 处理完整的消息
                        // 使用正则表达式匹配SSE消息格式
                        // 支持多种格式: "data: ...\n\n", "data:...\n\n", "data: ...\r\n\r\n"
                        const regex = /data:[ ]?(.*?)(\n|\r\n)/gs;
                        let match;
                        let lastIndex = 0;

                        // 查找所有完整的消息
                        while ((match = regex.exec(buffer)) !== null) {
                            const content = match[1];
                            processContent(content);
                            lastIndex = regex.lastIndex;
                        }

                        // 保留未处理的部分到缓冲区
                        if (lastIndex > 0) {
                            buffer = buffer.substring(lastIndex);
                        }

                        // 如果缓冲区过大但没有找到完整消息，尝试更宽松的处理
                        const MAX_BUFFER_SIZE = 100000; // 100KB
                        if (buffer.length > MAX_BUFFER_SIZE) {
                            // 尝试查找任何可能的data标记
                            const dataIndex = buffer.lastIndexOf('data:');
                            if (dataIndex >= 0) {
                                // 提取最后一个data标记后的内容
                                const partialContent = buffer.substring(dataIndex + 5).trim();
                                if (partialContent) {
                                    processContent(partialContent);
                                }
                            }

                            // 保留最后一部分可能的消息开头
                            buffer = buffer.substring(buffer.length - 1000);
                        }
                    }
                } catch (error) {
                    if (error instanceof Error && error.name === 'AbortError') {
                        // 请求被取消，不需要处理
                    } else {
                        if (onError) onError(error as Error);
                    }
                }
            };

            // 处理单条消息内容
            const processContent = (content: string): void => {
                try {
                    // 处理内容
                    let textContent = content;
                    
                    // 移除可能的引号（如果服务器发送的是带引号的字符串）
                    if (content.startsWith('"') && content.endsWith('"')) {
                        try {
                            textContent = JSON.parse(content); // 解析JSON字符串
                        } catch (e) {
                            // 如果解析失败，可能是引号内有未转义的引号，尝试手动处理
                            if (content.length > 2) {
                                textContent = content.substring(1, content.length - 1);
                            }
                        }
                    }
                    
                    // 处理转义字符：将文本中的 \\n 转换为实际的换行符
                    textContent = textContent.replace(/\\n/g, '\n');
                    textContent = textContent.replace(/\\r/g, '\r');
                    // 累积文本
                    accumulatedText += textContent;
                    
                    // 发送消息，保留原始格式
                    if (onMessage) {
                        onMessage({ 
                            content: textContent,
                            full_content: accumulatedText,
                            is_text: true
                        });
                    }
                } catch (error) {
                    // 即使解析失败，也尝试将原始内容发送给回调
                    if (onMessage) {
                        onMessage({ 
                            content: content,
                            parse_error: true 
                        });
                    }
                }
            };

            // 处理缓冲区内容
            const processBufferContent = (buffer: string): void => {
                if (buffer.startsWith('data: ')) {
                    const content = buffer.substring(6).trim();
                    processContent(content);
                } else if (buffer.startsWith('data:')) {
                    const content = buffer.substring(5).trim();
                    processContent(content);
                } else if (buffer.trim()) {
                    // 如果不是标准格式但有内容，尝试处理
                    processContent(buffer.trim());
                }
            };

            // 开始处理流
            processStream();
        })
        .catch(error => {
            if (onError) onError(error as Error);
        });

        // 返回一个对象，包含取消请求的方法
        return {
            close: () => {
                controller.abort();
            }
        };
    }
} 