<template>
    <div class="create-tool-dialog" id="create-tool-dialog">
        <el-dialog
            v-model="dialogVisible"
            width="45%"
            class="create-tool-dialog-container"
            append-to-body
            :show-close="false"
        >
            <template #header>
                <!-- 标题区域 -->
                <div class="dialog-header">
                    <h2 class="dialog-title">{{ t("createTool") }}</h2>
                    <div class="header-actions">
                        <l-img
                            @click="handleClose"
                            src="/static/images/close_icon.png"
                            w="20px"
                            h="20px"
                            class="close-btn"
                        ></l-img>
                    </div>
                </div>
            </template>
            <div class="dialog-background-box">
                <div class="dialog-background">
                    <!-- 表单内容区域 -->
                    <el-form
                        ref="toolFormRef"
                        :model="toolData"
                        :rules="rules"
                        label-position="top"
                        class="form-container"
                    >
                        <!-- 标题 -->
                        <el-form-item prop="title" class="form-field">
                            <div class="form-field-label">
                                {{ t("title") }}
                                <span class="required-star"> *</span>
                            </div>
                            <el-input
                                v-model="toolData.title"
                                :placeholder="t('titlePlaceholder')"
                                class="title-input"
                            ></el-input>
                        </el-form-item>

                        <!-- 描述 -->
                        <el-form-item prop="description" class="form-field">
                            <div class="form-label-with-hint-tips">
                                <div class="form-field-label">
                                    {{ t("description") }}
                                    <span class="required-star"> *</span>
                                </div>
                                <div class="form-hint">
                                    {{ t("maxCharacters") }}
                                </div>
                            </div>
                            <el-input
                                v-model="toolData.description"
                                type="textarea"
                                :rows="3"
                                :maxlength="120"
                                show-word-limit
                                :placeholder="t('descriptionPlaceholder')"
                                class="description-textarea"
                            ></el-input>
                        </el-form-item>

                        <!-- 提示词 -->
                        <el-form-item prop="prompt" class="form-field">
                            <div class="form-field-label">
                                {{ t("prompt") }}
                                <span class="required-star"> *</span>
                            </div>
                            <el-input
                                v-model="toolData.prompt"
                                type="textarea"
                                :rows="6"
                                :placeholder="t('promptPlaceholder')"
                                class="prompt-textarea"
                            ></el-input>
                        </el-form-item>
                    </el-form>
                </div>
            </div>

            <!-- 底部操作栏 -->
            <template #footer>
                <div class="dialog-footer">
                    <el-button @click="handleCancel" class="cancel-btn">{{
                        t("cancel")
                    }}</el-button>
                    <el-button
                        type="primary"
                        @click="submitForm"
                        :loading="submitting"
                        :disabled="submitting"
                        class="submit-btn"
                        >{{
                            submitting ? t("creating") : t("createTool")
                        }}</el-button
                    >
                </div>
            </template>
        </el-dialog>
    </div>
</template>

<script setup>
import { ref, computed, watch, reactive, nextTick } from "vue";
import { useI18n } from "vue-i18n";
import { ElMessage } from "element-plus";
import LImg from "@/components/l-img.vue";
import { ApiTextTool } from "@/api/api-text-tool";
import { isFormDataIdentical } from "@/utils/util.js";

const props = defineProps({
    visible: {
        type: Boolean,
        default: false,
    },
    editData: {
        type: Object,
        default: null,
    },
});

const emit = defineEmits(["update:visible", "cancel", "create"]);

const { t } = useI18n();

// 对话框显示控制
const dialogVisible = ref(false);

// 表单ref
const toolFormRef = ref(null);

// 文本工具字段映射配置
const TOOL_FIELD_MAPPINGS = [
    { current: "title", original: "title" },
    { current: "description", original: "description" },
    { current: "prompt", original: "prompt" },
];

// 监听props.visible变化
watch(
    () => props.visible,
    async (newVal) => {
        dialogVisible.value = newVal;
        if (newVal) {
            // 弹窗打开时，等待 DOM 更新完成后再填充数据
            await nextTick();
            if (props.editData) {
                fillFormWithEditData();
            } else {
                // 如果没有数据，重置表单
                resetForm();
            }
        }
    }
);

// 监听编辑数据变化
watch(
    () => props.editData,
    async (newData) => {
        if (newData && dialogVisible.value) {
            // 等待 DOM 更新完成后再填充数据
            await nextTick();
            fillFormWithEditData();
        }
    },
    { deep: true }
);

// 填充数据到表单（帮助用户快速填写）
const fillFormWithEditData = () => {
    if (props.editData) {
        console.log("Filling form with data for quick setup:", props.editData);
        toolData.value = {
            title: props.editData.title || "",
            description: props.editData.description || "",
            prompt: props.editData.prompt || "",
        };

        // 清除表单验证错误
        if (toolFormRef.value) {
            toolFormRef.value.clearValidate();
        }
    }
};

// 监听dialogVisible变化
watch(
    () => dialogVisible.value,
    (newVal) => {
        emit("update:visible", newVal);
        if (!newVal) {
            // 弹窗关闭时重置表单，但延迟执行避免闪烁
            setTimeout(() => {
                resetForm();
            }, 100);
        }
    }
);

// 工具数据
const toolData = ref({
    title: "",
    description: "",
    prompt: "",
});

// 提交状态
const submitting = ref(false);

// 表单验证规则
const rules = reactive({
    title: [
        {
            required: true,
            message: t("title") + " " + t("isRequired"),
            trigger: "blur",
        },
        {
            min: 2,
            max: 50,
            message: t("lengthShouldBe2To50Characters"),
            trigger: "blur",
        },
    ],
    description: [
        {
            required: true,
            message: t("description") + " " + t("isRequired"),
            trigger: "blur",
        },
        { max: 120, message: t("maxCharacters"), trigger: "blur" },
    ],
    prompt: [
        {
            required: true,
            message: t("prompt") + " " + t("isRequired"),
            trigger: "blur",
        },
    ],
});

// 关闭弹窗
const handleClose = () => {
    dialogVisible.value = false;
};

// 取消按钮
const handleCancel = () => {
    resetForm();
    dialogVisible.value = false;
    emit("cancel");
};

// 提交表单
const submitForm = async () => {
    if (submitting.value) return;

    toolFormRef.value.validate(async (valid) => {
        if (valid) {
            try {
                // 检查是否有快速填写数据，且当前表单数据与快速填写数据完全一致
                if (props.editData) {
                    const isDataIdentical = isFormDataIdentical(
                        toolData.value,
                        props.editData,
                        TOOL_FIELD_MAPPINGS
                    );

                    if (isDataIdentical) {
                        ElMessage.warning(t("dataUnchangedError"));
                        return;
                    }
                }

                submitting.value = true;

                // 创建新工具（使用填充的数据帮助用户快速填写）
                const submitData = {
                    title: toolData.value.title,
                    description: toolData.value.description,
                    prompt: toolData.value.prompt
                };

                const response = await ApiTextTool.createTool(submitData);

                // 发送成功事件
                emit("create", response.data);

                // 显示成功消息
                ElMessage.success(t("toolCreated"));

                // 关闭弹窗
                dialogVisible.value = false;

                // 重置表单
                resetForm();
            } catch (error) {
                console.error("Failed to submit tool:", error);
                // 不需要手动显示错误消息，axios封装会自动处理
            } finally {
                submitting.value = false;
            }
        }
    });
};

// 重置表单
const resetForm = () => {
    toolData.value = {
        title: "",
        description: "",
        prompt: "",
    };

    if (toolFormRef.value) {
        toolFormRef.value.resetFields();
        toolFormRef.value.clearValidate();
    }
};
</script>

